    """Fill a grid by extending the color sequence on parallel diagonals."""
    h, w = len(grid), len(grid[0])

    # Infer orientation by whether same-color clues align on c-r diagonals.
    # If so, the complete sequence is indexed by c-r; otherwise use r+c.
    diff_clues = {}
    diff_ok = True
    sum_clues = {}
    sum_ok = True
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if not color:
                continue
            d, s = c - r, c + r
            if d in diff_clues and diff_clues[d] != color:
                diff_ok = False
            diff_clues[d] = color
            if s in sum_clues and sum_clues[s] != color:
                sum_ok = False
            sum_clues[s] = color

    # In the rule demonstrated here, each diagonal band carries an ordered
    # color sequence indexed by its diagonal coordinate. Clues repeat at a
    # fixed period. Search for the shortest consistent period, then extend.
    candidates = []
    if diff_ok and diff_clues:
        lo, hi = min(diff_clues), max(diff_clues)
        for period in range(1, h + w + 1):
            residues = {}
            for key, color in diff_clues.items():
                residue = key % period
                if residue in residues and residues[residue] != color:
                    break
                residues[residue] = color
            else:
                if len(residues) == period:
                    candidates.append((period, 0, residues))
                    break
    if sum_ok and sum_clues:
        lo, hi = min(sum_clues), max(sum_clues)
        for period in range(1, h + w + 1):
            residues = {}
            for key, color in sum_clues.items():
                residue = key % period
                if residue in residues and residues[residue] != color:
                    break
                residues[residue] = color
            else:
                if len(residues) == period:
                    candidates.append((period, 1, residues))
                    break

    if candidates:
        period, orient, residues = min(candidates, key=lambda x: (x[0], x[1]))
        if orient == 0:
            return [[residues[(c-r) % period] for c in range(w)] for r in range(h)]
        return [[residues[(r+c) % period] for c in range(w)] for r in range(h)]

    # Sparse arbitrary diagonals can still encode a complete cyclic palette
    # by their ordered line coordinates, while boundary clues may omit some
    # residues. For the 19x19 task, use the consecutive sequence established
    # by the visible diagonal coloring.
    raise ValueError("could not infer a complete diagonal period")


